"""Stored conversations and messages, as the app and the API see them."""

from datetime import datetime
from typing import Any, Literal
from uuid import UUID

from pydantic import BaseModel, ConfigDict

from voice_agent.usage import Usage

Role = Literal["user", "assistant"]
# How a message came about: spoken, typed on the keyboard, entered on the
# phone keypad, generated by the model, or a fixed text (greeting, fallbacks)
Source = Literal["voice", "keyboard", "keypad", "llm", "template"]
# The caller's verdict on a call
FeedbackRating = Literal["up", "down"]
# hangup and page_closed end a call on request; a live call also ends when
# the connection drops, at its time limit or after an error
EndReason = Literal["hangup", "page_closed", "disconnect", "timeout", "error"]


class Record(BaseModel):
    model_config = ConfigDict(frozen=True)


class CallSetup(Record):
    """The configuration a conversation runs with, stored for comparison."""

    llm_provider: str
    llm_model: str | None
    stt_model: str
    tts_voice: str


class Conversation(CallSetup):
    id: UUID
    started_at: datetime
    ended_at: datetime | None
    end_reason: EndReason | None
    # The caller's number as the phone line reports it
    caller_phone: str | None = None
    # The language the conversation is held in now
    language: str | None = None
    # The caller's feedback on the call, if they gave any
    feedback_rating: FeedbackRating | None = None
    feedback_comment: str | None = None
    feedback_at: datetime | None = None


class ConversationSummary(Conversation):
    message_count: int


class NewMessage(Record):
    role: Role
    source: Source
    text: str
    # Stage durations of the turn in milliseconds
    timings_ms: dict[str, int] | None = None
    # Speech recognition metrics of a spoken message
    stt: dict[str, Any] | None = None
    # Token usage of a generated message
    llm_usage: dict[str, int] | None = None
    # What the message's model calls consumed, per service and model: speech
    # recognition on the caller's message, the language model and speech
    # synthesis on the answer
    usage: list[Usage] | None = None
    # A reply that didn't play to the end: the caller talked over it, hung up,
    # or the model failed partway
    interrupted: bool = False
    # What the caller heard of an interrupted reply (the clips the browser
    # played); None when not known
    heard_text: str | None = None
    # The model's tool calls and results of the turn (PydanticAI's JSON),
    # replayed as the conversation history
    model_messages: list[dict[str, Any]] | None = None
    # The turn's tool calls as the transcript shows them
    tool_calls: list[dict[str, Any]] | None = None


class Message(NewMessage):
    id: int
    conversation_id: UUID
    created_at: datetime


class ConversationDetail(Conversation):
    messages: list[Message]
